AD = 'Indonesian Army (TNI-AD)'
MAR = 'Indonesian Marine Corps (Korps Marinir)'

e('idn-org-overview', 'liaison', 'Forces', 'Indonesian National Armed Forces (TNI)', ['Battalion', 'Regiment', 'Division'], 'Organisation',
  'Two Services, Kostrad and Kodam: How Indonesia Organises Its Artillery',
  ['Land and amphibious fire support is split between the Army field artillery corps (Armed) and the Marine Corps (Korps Marinir, part of the Navy).',
   'Army artillery serves in two Strategic Reserve Command (Kostrad) divisional regiments for mobile projection, and in battalions under the regional commands (Kodam).'],
  ['Kostrad: Menarmed 1 (Divif 1) and Menarmed 2 (Divif 2) group CAESAR gun and ASTROS rocket battalions.',
   'Kodam battalions hold older 76mm and 105mm guns and M109A4-BE howitzers for regional defence; numbering reached at least Yonarmed 22 by August 2026.',
   'Doctrine comes from the Field Artillery Weapons Centre (Pussenarmed) and schooling from Pusdikarmed, both in Cimahi, West Java.',
   'Marine artillery serves in the three Marine Forces (Pasmar 1 to 3) with 122mm rocket launchers and 105mm guns.',
   'Not found in open sources: a full 2026 roster of battalions, or where each of the 56 CAESARs is held.'],
  ['An archipelago with weak roads and many ports favours wheeled, air-portable guns and rockets over large tracked brigades.',
   'Compare the US: its artillery sits mostly in divisions and corps fires brigades; Indonesia splits it between a strategic reserve and regional commands.'],
  [KEMHAN_2011, WIKI_MENARMED2, WIKI_YON1], 'Reported', '2026-11', ['idn-eq-caesar', 'idn-org-astros', 'idn-org-howitzers', 'idn-trn-pusdikarmed'])

e('idn-ttp-joint-fires', 'liaison', 'TTPs', 'TNI-AD (Pussenarmed) and Navy (Seskoal)', ['Theatre'], 'TTP',
  'From Seminars to Joint Fires: Linking Guns, Rockets and Missiles',
  ['Pussenarmed is rewriting field artillery doctrine to combine guns, rockets and long-range missiles into joint fires with the Navy and Air Force.'],
  ['National seminars at Pusdikarmed on the corps anniversaries (26 November 2024, 18 November 2025) shaped a 2025–2026 modernisation plan.',
   'The 2025 theme joined cannons, rockets, long-range missiles and multi-service interoperability.',
   'The Naval Command and Staff College presented a concept that adds naval gunfire to Army fires across land, sea and air.',
   'Both services put shared situational awareness and sensor-to-weapon links first.'],
  ['New long-range missiles cannot be used well without joint targeting, and an island country needs land, sea and air fires working together.',
   'Compare the US: joint fires rest on standing doctrine (JP 3-09) and Multi-Domain Task Forces; Indonesia is moving from seminars towards written procedures.'],
  [PUSJIANMAR, TNI_SEM], 'Confirmed', '2025-11', ['idn-trn-sgs26', 'idn-les-interop', 'idn-eq-itbm-khan', 'joint-org-support-relationships'])

e('idn-trn-sgs26', 'liaison', 'Training', 'TNI-AD, Korps Marinir and Air Force (TNI-AU)', ['Theatre'], 'Training',
  'Super Garuda Shield 26: A Combined Joint Land Strike',
  ['Indonesian Army, Marine and Air Force units fired a Combined Joint Land Strike with US forces on 4 and 7 September 2026 at the Baturaja Combat Training Center, South Sumatra.'],
  ['Army ASTROS II Mk6 and Marine RM-70 Vampire launchers fired beside Iowa Army National Guard HIMARS.',
   'Indonesian F-16s and Indonesian and US AH-64 Apaches struck the same target area.',
   'Planners from the TNI, the US 4th Infantry Division and Marine Rotational Force–Darwin set firing windows and airspace safety.',
   'Next Generation Command and Control software shared target data across national command posts.',
   'Crews rehearsed repeatedly at Martapura and Baturaja before live firing.'],
  ['An annual live joint strike builds habits between Army rockets, Marine artillery and aviation, and tests coalition digital links under real safety rules.',
   'Compare the US: standing joint fires cells sit in division and corps headquarters; Indonesia practises cross-service fires at scale in flagship exercises.'],
  [SGS, SGS_VID, SGS_END], 'Confirmed', '2026-09', ['idn-les-interop', 'idn-org-astros', 'idn-eq-marine-mlrs', 'joint-eq-m142'])

e('idn-les-interop', 'liaison', 'Lessons', 'TNI-AD and Korps Marinir', ['Division'], 'Lesson',
  'Many Suppliers, One Fire Plan: Interoperability Friction',
  ['Super Garuda Shield 26 showed how hard it is to synchronise Indonesian and allied indirect fire; planners needed aligned procedures and repeated rehearsals.'],
  ['US 4th Infantry Division fires planners called the coordination across US Army, US Marine and Indonesian units one of the hardest tasks in combined arms.',
   'Staffs had to align technical standards, safety rules, communications and doctrine across ASTROS II, RM-70 Vampire and HIMARS.',
   'Repeated run-throughs found errors before live firing.',
   'Digital links sped up data sharing, but only worked when paired with joint crew drills.'],
  ['Indonesia fields guns and rockets from France, Brazil, the Czech Republic, China and Türkiye, so integration is an internal problem as well as a coalition one.',
   'Compare the US: US Army and Marine units share common interfaces; Indonesia bridges mixed foreign systems through rehearsal and custom digital gateways.'],
  [SGS, PUSJIANMAR], 'Confirmed', '2026-09', ['idn-trn-sgs26', 'idn-eq-bms-taca', 'idn-ttp-joint-fires', 'joint-eq-asca'])

e('idn-eq-caesar', 'cannon-artillery', 'Equipment', AD, ['Battalion'], 'Equipment',
  'CAESAR: Indonesia’s Main Modern Gun',
  ['The French KNDS CAESAR 155mm/52-calibre 6×6 wheeled howitzer is the Army’s main modern tube artillery.',
   'Reported: 56 delivered, and a June 2025 letter of intent covers more, built locally.'],
  ['Reported: bought in three batches (2014, 2016, 2017) and held by Kostrad battalions including Yonarmed 9 (Divif 1) and Yonarmed 12 (Divif 2, Ngawi).',
   'Reported: Sherpa 6×6 chassis, crew of three to five, 18 rounds on board, automatic laying, in and out of action in under a minute.',
   'Reported: up to six rounds a minute and 40 km with LU-family ammunition; a Malang city government release gives 45 km.',
   'Reported: at Indo Defence 2025 KNDS signed for more CAESARs and local production of guns and 155mm ammunition.'],
  ['Long reach and fast shoot-and-scoot on wheels suit Indonesian roads and bridges; local assembly cuts dependence on foreign support.',
   'Compare the US: the US Army uses the tracked 39-calibre M109A7 and towed M777A2; Indonesia’s main modern gun is a wheeled 52-calibre truck gun.'],
  [JANES_KNDS, AR_CAESAR, MALANG], 'Reported', '2026-07', ['idn-org-howitzers', 'idn-sus-ammo', 'idn-eq-precision-munitions', 'ukr-ttp-roving-gun'])

e('idn-org-howitzers', 'cannon-artillery', 'Forces', 'TNI-AD and Korps Marinir', ['Battalion'], 'Organisation',
  'Tracked, Towed and Amphibious Guns Beyond CAESAR',
  ['Besides CAESAR, Indonesia keeps tracked 155mm howitzers and towed 105mm and 76mm guns in regional Army battalions and the Marines.',
   'Reported: the Marines are studying the 105mm LG1 Mk III to upgrade amphibious gun support.'],
  ['Reported: Yonarmed 4 (Kodam III/Siliwangi) operates M109A4-BE 155mm tracked howitzers.',
   'Regional battalions keep towed guns, such as Yonarmed 15/76 (Kodam II/Sriwijaya); Reported: Yonarmed 8/105 and Yonarmed 11/76 also do.',
   'Marine Pasmar 2 lands 105mm towed howitzers with amphibious armour in beach-landing exercises at Banongan, East Java.',
   'Reported: Marine stocks include French LG1 105mm guns.',
   'Reported: light-gun battalions also take on territorial tasks such as border patrols on the Malaysian border.'],
  ['Light towed guns still suit beaches, jungle and scattered garrisons where heavy 155mm vehicles cannot go; tracked M109s keep an armoured gun in Java.',
   'Compare the US: it retired 76mm guns long ago and standardised on 105mm and 155mm; Indonesia runs all three calibres.'],
  [LIMA_KASAD, KOMANDO_LG1, ANTARA_PASMAR], 'Reported', '2026-09', ['idn-eq-caesar', 'idn-org-overview', 'usa-eq-m119a3', 'joint-eq-m777a2'])

e('idn-eq-mo3', 'cannon-artillery', 'Equipment', 'TNI-AD, Korps Marinir and TNI-AU', ['Battalion'], 'Equipment',
  'Pindad Mo-3: The 81mm Battalion Mortar',
  ['The Indonesian-designed Pindad Mo-3 (MO-3-81 SB) 81mm smoothbore mortar is the standard battalion mortar of Army and Marine infantry.',
   'It received a Ministry of Defence trial certificate on 1 July 2015 (valid to July 2018).'],
  ['Reported: 41.3 kg, 1.27 m barrel, five-soldier crew in the battalion mortar platoon.',
   'Reported: range 91 m to 5,935 m at 45° to 85.2° elevation.',
   'Reported: 8 to 16 rounds a minute sustained, 20 to 30 in short bursts.',
   'Marines of the 10th Marine Infantry Battalion fired it with small drones during Keris MAREX 2024 on Singkep (13 November 2024).'],
  ['An organic mortar gives light, airborne and amphibious infantry immediate high-angle fire; domestic manufacture secures supply.',
   'Compare the US: the Mo-3 matches the M252 81mm mortar in calibre, crew role and place in the infantry battalion.'],
  [PINDAD_AR, MAREX, WIKI_MO3], 'Confirmed', '2024-11', ['idn-eq-aldalbak', 'idn-eq-observer-uav', 'joint-eq-m252a1'])

e('idn-eq-itbm-khan', 'rocket-missile-artillery', 'Equipment', AD, ['Battalion'], 'Equipment',
  'ITBM-600 and KHAN: Southeast Asia’s First Modern Ballistic Missile',
  ['Reported: Indonesia has fielded the Turkish Roketsan multi-calibre launcher (locally ITBM-600) and the KHAN short-range ballistic missile, the first modern SRBM in Southeast Asia.',
   'Reported: Yonarmed 22 made the first disclosed live firing on 20 October 2026 in East Kalimantan, with guided 122mm rockets.'],
  ['Reported: chosen at Indo Defence 2022; a Tatra 8×8 launcher fires 122, 230, 300 and 610mm munitions from 10 to 280 km.',
   'Reported: the 610mm KHAN (export Bora) weighs about 2,500 kg, has a 470 kg warhead, reaches 80 to 280 km and uses satellite and inertial guidance; stated accuracy 10 m or better.',
   'Reported: launchers appeared near Raipur, East Kalimantan, around August 2025; Yonarmed 22’s permanent base opened at Loa Kulu, Kutai Kartanegara, in August 2026.',
   'Reported: a battery has launchers, command vehicles, resupply trucks, meteorological and maintenance elements.',
   'Reported: on 20 October 2026 crews fired a pilot round and three guided 122mm rockets; sources differ on whether they were TRG-122 or laser-guided TRLG-122.'],
  ['Reported: basing in East Kalimantan covers the new capital and the northern sea approaches, including the Makassar Strait and Sulawesi Sea.',
   'Compare the US: like HIMARS, one launcher fires both rockets and ballistic missiles, but with Turkish rather than US munitions. No KHAN live firing by Indonesian crews has been disclosed.'],
  [JANES_ITBM, DSA_ITBM, CNA_KHAN, LOWY, TURDEF], 'Reported', '2026-10', ['idn-eq-precision-munitions', 'idn-les-propellant', 'idn-eq-av-ucf', 'joint-eq-m142', 'joint-eq-rkt-munitions'])

e('idn-org-astros', 'rocket-missile-artillery', 'Forces', 'TNI-AD (Kostrad)', ['Battalion'], 'Organisation',
  'ASTROS II Mk6: The Strategic-Reserve Rocket Battalions',
  ['The Army operates the Brazilian Avibras ASTROS II Mk6 rocket system in Kostrad battalions; official reporting confirms live firing of SS-60 and SS-80 rockets by Yonarmed 10.'],
  ['Yonarmed 10 (Kostrad) fires SS-60 and SS-80 rockets; Reported: Yonarmed 1 in Singosari, Malang (renamed 1 March 2024 under Menarmed 2) also operates ASTROS.',
   'Reported: Yonarmed 1 has three firing batteries, a headquarters battery and an observation platoon.',
   'Reported: on 6×6 and 4×4 trucks, air-transportable, up to 300 km depending on the rocket.',
   'ASTROS launchers fired in the Super Garuda Shield 26 joint strike beside US HIMARS.'],
  ['Reported: moving Yonarmed 1 from a regional command to Kostrad put the rockets near airbases and ports for deployment anywhere in the country.',
   'Compare the US: ASTROS fills a role like HIMARS, but Indonesia’s confirmed firings use unguided area rockets, not guided GMLRS.'],
  [TNI_ASTROS, SGS, WIKI_YON1], 'Confirmed', '2026-09', ['idn-eq-av-ucf', 'idn-trn-sgs26', 'idn-eq-itbm-khan', 'joint-eq-m142'])

e('idn-eq-marine-mlrs', 'rocket-missile-artillery', 'Equipment', MAR, ['Battalion'], 'Equipment',
  'Marine 122mm Rocket Launchers and the R-Han 122B',
  ['The Marines operate Czech RM-70 Vampire, older RM-70 Grad and Chinese Norinco Type 90B 122mm launchers for amphibious operations.',
   'A domestic consortium developed the R-Han 122B rocket, but its adoption is not confirmed.'],
  ['Reported: 36 RM-70 Vampire (8 in 2016, 28 in 2022–2023, some assembled locally), 9 RM-70 Grad (about 2003) and at least 4 Type 90B (2015, up to 40 km).',
   'Pasmar 1 to 3 use them in landings such as Banongan and in joint fires such as Super Garuda Shield 26.',
   'Reported: RM-70 batteries use Slovak Aligator Master 4×4 observer vehicles.',
   'The Ministry of Defence, Pindad, Dahana, PT DI and LAPAN built the R-Han 122B (Reported: 64 kg, 18 kg warhead, about 15 to 30 km); a 2021 study rated it TRL 7 and not yet adopted.'],
  ['Saturating 122mm rockets suppress coastal defences quickly in a landing; local assembly and rockets aim to cut dependence on imported stocks.',
   'Compare the US: the Marine Corps replaced area rockets with precision HIMARS; Indonesian Marines still invest in unguided saturation launchers.'],
  [WIKI_NAVY, SGS, IARJET, CAKRAWALA], 'Reported', '2026-09', ['idn-trn-sgs26', 'idn-org-astros', 'idn-eq-observer-uav', 'rus-eq-tornado-g'])

e('idn-trn-anka', 'loitering-munitions', 'Training', 'Air Force (TNI-AU) and Naval Aviation (Puspenerbal)', ['Theatre'], 'Training',
  'ANKA: Armed MALE Drones and Their Operators',
  ['Reported: Indonesia is taking 12 Turkish Aerospace ANKA-S armed medium-altitude long-endurance drones under a 2023 contract of about $300 million.',
   'Reported: Navy aviators finished five months of pilot and sensor-operator training in Ankara, June to November 2026.'],
  ['Reported: six built in Türkiye and six assembled by PT Dirgantara Indonesia under technology transfer.',
   'Reported: up to 30 hours aloft and 30,000 ft, with day and thermal cameras, synthetic aperture radar and MAM-L and Cirit guided munitions.',
   'Reported: the Air Force received the first aircraft in September 2025; later deliveries are not disclosed.',
   'Reported: the trained Wing Udara 2 officers will instruct others, for surveillance over the southern Malacca Strait and North Natuna Sea.'],
  ['Persistent armed drones close maritime surveillance gaps and cue long-range fires without risking crews; training at the maker speeds conversion.',
   'Compare the US: ANKA does a smaller version of the MQ-9 Reaper’s job. Open sources do not say how the 12 are split between Air Force and Navy.'],
  [GBP_ANKA, ENV_ANKA], 'Reported', '2026-11', ['idn-eq-ucav', 'idn-eq-observer-uav', 'idn-eq-axys'])

e('idn-eq-ucav', 'loitering-munitions', 'Equipment', 'TNI-AU and national industry', ['Theatre'], 'Equipment',
  'Elang Hitam, Kizilelma and CH-4: Three Paths to Armed Drones',
  ['Reported: Indonesia combines its own armed drone (Elang Hitam) with foreign jet-powered unmanned combat aircraft (Bayraktar Kizilelma) and existing Chinese CH-4s.'],
  ['Reported: returned to military development in October 2024, Elang Hitam first flew on 28 July 2025 at Kertajati, West Java.',
   'Reported: 16 m wingspan, 1,300 kg take-off weight, 300 kg payload, 30 hours, planned rockets and MAM-L/MAM-C guided munitions.',
   'Reported: at SAHA 2026 (May 2026) Republikorp and Baykar signed a framework for 12 Kizilelma from 2028, with an option for 48 more.',
   'Reported: Kizilelma is designed for close air support, reconnaissance, air-defence suppression and strike from an internal weapons bay.'],
  ['Buying from several countries and building at home reduces dependence on one supplier and grows local aerospace skills.',
   'Compare the US: the Collaborative Combat Aircraft programme is built by US firms; Indonesia mixes home-grown prototypes with Turkish co-production.'],
  [WIKI_ELANG, JG_KIZ, EAT_KIZ], 'Reported', '2026-11', ['idn-trn-anka', 'idn-eq-minibe'])

e('idn-eq-minibe', 'loitering-munitions', 'Equipment', 'TNI-AD and PT Pindad', ['Battalion'], 'Equipment',
  'Minibe: Pindad’s Small Loitering Munition',
  ['Reported: state-owned PT Pindad developed the Minibe, a small electric fixed-wing loitering munition to give units their own precision strike.',
   'Reported: shown at Indo Defence 2022; reaches 25 km with a 0.8 kg warhead.'],
  ['Reported: 1.3 m wingspan, 6 kg take-off weight.',
   'Reported: up to 250 km/h, 15 minutes’ endurance.',
   'Reported: the small warhead suits light vehicles, exposed crews and point targets, not heavy armour.',
   'Reported: still described as under development in January 2023. Not found in open sources: production numbers, fielding dates or use in Army battalions as of November 2026.'],
  ['A domestic loitering munition offers cheap precision strike beyond mortar range without spending guided shells.',
   'Compare the US: it fills a niche like Switchblade 300, but numbers in service are unconfirmed.'],
  [CNBC_MINIBE, GNFI_MINIBE], 'Reported', '2023-01', ['idn-eq-ucav', 'idn-eq-mo3', 'usa-eq-switchblade'])

e('idn-eq-precision-munitions', 'ammunition-effects', 'Equipment', AD, ['Battalion'], 'Equipment',
  'Guided Rockets and Missiles Join Unguided Salvos',
  ['Reported: the ITBM-600 brings guided 122mm rockets (TRG-122) and 610mm KHAN ballistic missiles alongside unguided SS-60/SS-80 rockets and 155mm shells.'],
  ['Reported: TRG-122 weighs about 76 kg with a 13.5 kg steel-ball fragmentation warhead, 13 to 30 km, inertial plus satellite guidance; stated accuracy 10 m or better.',
   'Reported: the launcher also takes laser-guided TRLG-122 and TRLG-230 (70 km) rockets for point or moving targets marked by a drone.',
   'Reported: KHAN carries about 470 kg to 80–280 km, with anti-jamming and inertial-only fallback guidance.',
   'Reported: CAESAR fires the French LU family (HE, smoke, illumination, practice) and extended-range shells; Indonesian stocks are not disclosed.'],
  ['Guided rounds cut the number fired per target and the ammunition shipped between islands; inertial fallback keeps them usable under GPS jamming.',
   'Compare the US: TRG-122 and KHAN mirror the GMLRS and ATACMS/PrSM layers; no guided 155mm shell like Excalibur has been disclosed for Indonesia.'],
  [DSA_ITBM, JANES_ITBM, TURDEF, AR_CAESAR], 'Reported', '2026-10', ['idn-eq-itbm-khan', 'idn-eq-caesar', 'joint-eq-rkt-munitions'])

e('idn-pol-cluster', 'ammunition-effects', 'Forces', 'TNI (joint)', ['Theatre'], 'Policy',
  'Cluster Munitions: Signed but Not Ratified',
  ['Indonesia signed the Convention on Cluster Munitions and supports it in diplomacy, but had not ratified it as of September 2025.',
   'Treaty monitors believe Indonesia still holds undeclared cluster munitions.'],
  ['Indonesia attended the 2008 Dublin conference and spoke for a world free of cluster munitions at the 2011 and 2012 meetings of States Parties.',
   'The treaty registry lists it as the only Asia-Pacific signatory that has not ratified, one of 12 such signatories against 112 States Parties.',
   'In September 2025 the Cluster Munition Coalition said Indonesia is thought to hold stocks and urged ratification and destruction.',
   'Not found in open sources: any official statement of types, quantities or destruction plans.'],
  ['Staying a non-ratifying signatory keeps legacy area weapons legally unclear while staying aligned with humanitarian norms.',
   'Compare the US: neither is a State Party, but the US never signed and openly transfers cluster munitions; Indonesia signed and does not acknowledge stocks.'],
  [CCM_SP, CMC, CCM_IDN], 'Confirmed', '2025-09', ['idn-eq-precision-munitions', 'kpa-eq-chem-cluster'])

e('idn-eq-observer-uav', 'target-acquisition', 'Equipment', 'TNI-AD and Korps Marinir', ['Battalion'], 'Equipment',
  'Observation Platoons and Target-Observer Drones',
  ['Indonesian artillery and Marine units pair forward observers (Jaupan) and observation platoons with target-observer drones and small unmanned aircraft.',
   'Reported: Pussenarmed feeds drone video straight into digital command networks.'],
  ['Reported: rocket battalions such as Yonarmed 1 have an organic observation platoon beside three firing batteries.',
   'Reported: Marine RM-70 batteries use Slovak Aligator Master 4×4 armoured observer vehicles.',
   'Reported: observers use digital binoculars that send target coordinates electronically to SISBAK Mortir fire control.',
   'Marine infantry combined small drones with Mo-3 mortar firing during Keris MAREX 2024.',
   'Reported: Pussenarmed showed target-observer drones linked to PT Len’s AXYS-ISR system.'],
  ['Jungle canopy and islands block ground observation, so organic drones are needed to use rockets and 155mm guns at 30 to 45 km.',
   'Compare the US: like US fire support teams adding small drones, but at an earlier stage of fielding.'],
  [MAREX, HARIFF_PANG, WIKI_YON1], 'Reported', '2026-09', ['idn-eq-aldalbak', 'idn-eq-axys', 'idn-eq-mo3', 'usa-org-fist'])

e('idn-eq-wlr88', 'target-acquisition', 'Equipment', 'TNI-AD (Pussenarmed)', ['Regiment'], 'Equipment',
  'WLR-88: A Home-Built Weapon-Locating Radar',
  ['Reported: Pussenarmed and PT Elektronika Utama ITB developed the WLR-88 weapon-locating radar to find enemy guns.',
   'Reported: the prototype tracks incoming rounds out to 20 km and classifies the weapon that fired.'],
  ['Reported: built under a defence research programme, it computes the firing point from the projectile’s path.',
   'Reported: trialled in a Menarmed 2 (Kostrad) integrated live-fire exercise.',
   'Reported: on 23 March 2022 the Army Chief of Staff inspected it at Pusdikarmed and called for certification trials and more range.',
   'Reported: Parliament’s Defence Commission (Komisi I) inspected it as a domestic industry milestone.',
   'Not found in open sources: production, longer-range versions or issue to units since 2023.'],
  ['A domestic counter-battery radar avoids export limits, but 20 km is half the range of Indonesia’s own CAESAR.',
   'Compare the US: at a reported 20 km, WLR-88 reaches less than half as far as the AN/TPQ-53.'],
  [DETIK_WLR, VIVA_WLR, LIMA_WLR], 'Reported', '2022-03', ['idn-eq-observer-uav', 'idn-les-drones-cyber', 'usa-eq-tpq53'])

e('idn-trn-pusdikarmed', 'technical-fire-direction', 'Training', 'TNI-AD (Pussenarmed, Kodiklatad, Military Academy)', ['Corps'], 'Training',
  'Pusdikarmed: The Gunnery School and Virtual Simulation',
  ['The Field Artillery Education Centre (Pusdikarmed) in Cimahi, West Java, trains artillery officers, NCOs and soldiers in technical gunnery.',
   'The Military Academy (Akmil) is adding virtual observer and fire-direction simulation, planned to link with regional training centres.'],
  ['Pusdikarmed is required to keep its curriculum up to date with new technology and weapons.',
   'It trains large cohorts under the Army training command (for example 1,673 students at one graduation); Reported: Pussenarmed also runs weapon-system courses.',
   'At Akmil, simulation module NA5107 trains cadets as forward observers: fix the target, then send accurate corrections.',
   'Plans to link academy simulators with regional centres for live-virtual-constructive training note instructor skills and budget limits.'],
  ['Simulation saves live ammunition and lets crews practise digital calls for fire before they reach the range.',
   'Compare the US: Pusdikarmed is Indonesia’s counterpart to the Fires Center of Excellence at Fort Sill; its networked simulation is still being phased in.'],
  [PUSDIK_VM, PUSDIK_PROF, AKMIL], 'Confirmed', '2026-11', ['idn-org-overview', 'idn-eq-aldalbak', 'usa-trn-cannon-specialties'])

e('idn-eq-aldalbak', 'technical-fire-direction', 'Equipment', 'TNI-AD and Korps Marinir', ['Battery'], 'Equipment',
  'ALDALBAK and SISBAK Mortir: Digital Fire Control from Local Industry',
  ['Reported: PT Hariff Dipa Persada makes ALDALBAK for artillery fire control and SISBAK Mortir for computerised mortar fire direction.',
   'Reported: both replace manual plotting and voice radio with digital target messages and automatic ballistic computing.'],
  ['Reported: ALDALBAK links observer instruments, the fire direction centre and the guns, and works with the battlefield management system.',
   'Reported: SISBAK Mortir takes target data straight from observers’ digital binoculars, removing voice errors.',
   'Reported: it computes azimuth and elevation within seconds, helps choose ammunition and sends firing orders to the crew.',
   'Reported: a two-week conversion course: Pindad teaches the mortar in week one, Hariff the fire control in week two.',
   'Reported: in August 2025 the Marine Corps commander inspected SISBAK Mortir and BMS CY-16H for Marine vehicles.'],
  ['Automatic computing shortens the sensor-to-shooter cycle and cuts wasted rounds for units with no built-in digital fire control.',
   'Compare the US: they do the jobs of AFATDS and the M95/M96 mortar fire control system, but are made at home.'],
  [HARIFF_ALD, HARIFF_PANG, HARIFF_SIS], 'Reported', '2025-08', ['idn-eq-mo3', 'idn-eq-bms-taca', 'idn-eq-observer-uav', 'usa-eq-afatds-arch'])

e('idn-eq-av-ucf', 'technical-fire-direction', 'Equipment', 'TNI-AD (Kostrad)', ['Battery'], 'Equipment',
  'AV-UCF: Correcting Rocket Salvos by Radar',
  ['Reported: ASTROS II Mk6 batteries use the Brazilian AV-UCF fire control unit, whose radar tracks fired rockets to correct the next salvo.',
   'Reported: ITBM-600 batteries have their own meteorological and command vehicles.'],
  ['Reported: the AV-UCF radar tracks the flight of rockets after launch.',
   'Reported: it measures how far they drift from the planned path and computes corrections for later salvos at long range.',
   'Reported: in ITBM-600 batteries, meteorological units supply weather data before guided rockets or missiles are fired.'],
  ['Unguided SS-60 and SS-80 rockets spread widely at long range; radar corrections keep salvos accurate without forward observers.',
   'Compare the US: HIMARS fires GPS-guided rockets, so US batteries need no trajectory-tracking radar vehicle.'],
  [WIKI_YON1, DSA_ITBM], 'Reported', '2026-10', ['idn-org-astros', 'idn-eq-itbm-khan', 'usa-eq-ballistic-compare'])

e('idn-eq-axys', 'digital-fires-c2', 'Equipment', 'TNI-AD (Pussenarmed)', ['Division'], 'Equipment',
  'AXYS-ISR: Drone Feeds over a Sovereign Data Link',
  ['Reported: Pussenarmed sends reconnaissance drone feeds into PT Len Industri’s AXYS-ISR command system over an Indonesian encrypted tactical data link.',
   'Analysis: this entry rests on one Indonesian defence-magazine report (September 2026) that could not be opened for checking; no other open source describes AXYS-ISR. PT Len does hold a military certificate for a tactical data link system.'],
  ['Reported: reconnaissance drones stream live video over PT Len’s tactical data link.',
   'Reported: AXYS-ISR fuses drone imagery and target data into one shared picture.',
   'Reported: the same data goes to infantry perimeter systems and air defence radars.',
   'Reported: domestic encryption aims to stop interception of targeting links.'],
  ['Indonesian-made encrypted links protect the drone-to-gun chain from electronic attack and foreign software limits.',
   'Compare the US: it plays a sensor-fusion role like a JADC2 tactical gateway, built on PT Len’s own design.'],
  [S('Penandatanganan dan Penyerahan Sertifikat Kelaikan Militer Communication Tactical Data Link System', 'Kementerian Pertahanan (Puslaik)', '', 'https://www.kemhan.go.id/puslaik/?p=6778')], 'Analysis', '2026-09', ['idn-eq-observer-uav', 'idn-eq-bms-taca', 'idn-les-drones-cyber', 'ukr-eq-delta'])

e('idn-eq-bms-taca', 'digital-fires-c2', 'Equipment', 'TNI-AD and Korps Marinir', ['Brigade'], 'Equipment',
  'BMS CY-16H and TACA: Bridging Many Systems',
  ['Reported: PT Hariff Dipa Persada’s BMS CY-16H battlefield management system and TACA command suite give digital command and translate between different systems.',
   'Reported: BMS CY-16H is in use on over 400 vehicles, with 240 dismounted users and 17 command posts.'],
  ['Reported: versions fit artillery, amphibious vehicles, Navy ships and landing craft, and command posts.',
   'Reported: it links to ALDALBAK and SISBAK Mortir so calls for fire pass digitally between echelons.',
   'Reported: TACA scales from FIELD (front line) and CENTER (headquarters) to GROUP (Army–Navy–Air Force) and GATEWAY (translation between weapon systems).',
   'Reported: fitted to Turkish BMC Kirpi armoured vehicles.'],
  ['With equipment from many countries, translation software is how Indonesia unites targeting without replacing older hardware.',
   'Compare the US: BMS CY-16H is like the JBC-P mounted network; TACA GATEWAY solves a mixed-vendor problem US forces do not have at home.'],
  [HARIFF_PANG, HARIFF_TACA, HARIFF_KIRPI], 'Reported', '2025-08', ['idn-eq-aldalbak', 'idn-eq-axys', 'idn-les-interop'])

e('idn-les-drones-cyber', 'counterfire-survivability', 'Lessons', AD, ['Corps'], 'Lesson',
  'Lessons from Drone Swarms and Cyber Attack',
  ['Reported: from the Russia–Ukraine war and Middle East drone and missile strikes, Army leaders concluded that cheap drones and cyber attack change how artillery and armour must fight, not that they are obsolete.',
   'Analysis: this rests on one Indonesian defence-magazine report (September 2026) that could not be opened for checking.'],
  ['Reported: in September 2026 the Army spokesman said cheap drones disabling armour show artillery, armour, infantry, aviation and air defence must work as one network under cyber and electronic-warfare cover.',
   'Reported: drones and digital systems are treated as force multipliers for survival, speed and precision, not replacements.',
   'Reported: the Military Academy and officer and NCO schools now teach digital literacy, unmanned systems, cyber security and data-driven decisions.'],
  ['Static batteries and command posts are quickly found by drones, counter-battery radar and cyber intrusion; schools must teach the counters.',
   'Compare the US: the assessment matches US lessons from Ukraine on counter-drone defence and command-post survival; Indonesia is still building them into its schools.'],
  [], 'Analysis', '2026-09', ['idn-eq-shorad', 'idn-eq-axys', 'les-cannon-drones-gps'])

e('idn-eq-shorad', 'counterfire-survivability', 'Equipment', 'TNI-AD (Air Defence Artillery, Arhanud)', ['Battalion'], 'Equipment',
  'Arhanud: Air and Drone Defence for the Guns',
  ['Army air defence battalions protect troops, artillery and key sites with ForceSHIELD/Starstreak, Mistral, older Grom missiles and 57mm guns, and mobile counter-drone systems.',
   'Reported: domestic and Franco-Indonesian programmes add jamming and kinetic anti-drone vehicles.'],
  ['Reported: a 2014 contract over £100 million bought five ForceSHIELD batteries: Starstreak missiles (over Mach 3, 7 km), ControlMaster200 radars and RAPIDRanger launchers on VAMTAC vehicles.',
   'Yonarhanud 10 fired Mistral in Super Garuda Shield 26; Reported: the Jakarta regiment also holds Grom missiles and 57mm S-60 guns.',
   'Reported: Pindad’s SPS-1 on the Maung MV3 combines a radio drone jammer with a 12.7mm machine gun (2024).',
   'Reported: KNDS agreed in June 2025 to add counter-drone kit to the P2 Tiger vehicle.'],
  ['Wheeled guns and launchers survive by moving fast under layered short-range air and drone defence.',
   'Compare the US: a point-defence role like M-SHORAD and M-LIDS, spread across more mixed legacy and prototype systems.'],
  [DEFIQ, JANES_KNDS, WIKI_ARHANUD, SGS_AD], 'Reported', '2026-09', ['idn-les-drones-cyber', 'idn-eq-caesar', 'usa-org-cf-ada-protection'])

e('idn-sus-ammo', 'sustainment', 'Forces', 'PT Pindad and Ministry of Defence', ['Theatre'], 'Organisation',
  'Building Shells at Home: The Batulicin Factory',
  ['Reported: Indonesia is expanding ammunition production beyond Pindad’s current 5.56mm to 105mm range to include 155mm shells.',
   'Reported: on 4 July 2026 the Defence Minister broke ground on a new Pindad munitions factory at Batulicin, South Kalimantan.'],
  ['Reported: Pindad now makes small, medium and large rounds up to 105mm, and grenades.',
   'Reported: a 2024 agreement with Rheinmetall Denel Munition set up cooperation on a new factory and shell development.',
   'Reported: at Indo Defence 2025 KNDS signed for local production of 155mm CAESAR ammunition.',
   'Reported: the Batulicin plant in Tanah Bumbu will make rounds from small arms to large-calibre artillery.'],
  ['Making large shells in Kalimantan spreads war reserves away from Java and cuts dependence on imports for the CAESAR fleet.',
   'Compare the US: like the US expansion of 155mm production since 2022, Indonesia is adding lines through European partners.'],
  [DM_FACT, JANES_KNDS], 'Reported', '2026-07', ['idn-les-propellant', 'idn-eq-caesar', 'joint-eq-sus-production'])

e('idn-les-propellant', 'sustainment', 'Lessons', 'TNI-AD, PT Pindad and PT Dahana', ['Theatre'], 'Lesson',
  'Propellant and the Cost of a Mixed Fleet',
  ['Reported: running rockets and missiles from several countries in several calibres creates a heavy supply and propellant burden across the islands.',
   'Reported: Indonesia is tackling propellant shortages through state consortia, foreign partners and research on palm-oil waste.'],
  ['Reported: analysts of the October 2026 ITBM firing noted that four calibres (122, 230, 300, 610mm) widen the supply problem; ammunition and maintenance are the real measure of combat power.',
   'Reported: in January 2025 a Pindad–Dahana consortium was announced to speed up a domestic propellant factory.',
   'Reported: on 30 September 2025 Pindad and D&M Holding signed to build an Indonesian–US–European energetics centre.',
   'Reported: in November 2026 Pindad described a pilot turning oil-palm waste into propellant cellulose: 50 tonnes a year in 2027, up to 1,000 tonnes later.'],
  ['Domestic shell cases are of little use in a long war if propellant must still be imported.',
   'Compare the US: both see energetics as a bottleneck; Indonesia is unusual in testing palm-oil waste as a feedstock.'],
  [DSA_ITBM, DM_HOLD, GAPKI, DM_FACT], 'Reported', '2026-11', ['idn-sus-ammo', 'idn-eq-itbm-khan', 'joint-eq-sus-bottlenecks'])

